test:
def test_member_values():
    assert OrderStatus.PENDING.value == 'pending', "PENDING must have value 'pending'"
    assert OrderStatus.SHIPPED.value == 'shipped', "SHIPPED must have value 'shipped'"

def test_members_are_distinct():
    assert OrderStatus.PENDING != OrderStatus.SHIPPED, 'different members must not be equal'

def test_lookup_by_value():
    assert OrderStatus('delivered') == OrderStatus.DELIVERED, "OrderStatus('delivered') must return DELIVERED"
